import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader - Keeping strictly for structure compliance, though not used for text here */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ElasticCheckmarkProps = Record<string, any>;

const ElasticCheckmark: React.FC<ElasticCheckmarkProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  checkColor = "#4ADE80", // Vibrant green
  glowColor = "#22c55e", // Slightly darker green for glow
  size = 200,
  strokeWidth = 10,
  glowIntensity = 0.6,
  durationInSeconds = 4,
}) => {
  // Not using fonts, but keeping hook call for stability/convention
  useFontLoader([]); 

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // --- Animation Physics ---

  // 1. Entrance Spring (Scale & Overshoot)
  // Low damping (9) creates the "overshoot" and "snap back".
  // Mass (0.8) makes it feel "springy".
  const entranceSpring = spring({
    frame,
    fps,
    config: {
      damping: 9,
      stiffness: 110,
      mass: 0.8,
    },
  });

  // 2. Micro Wobble
  // A rotational wobble that settles as the checkmark lands.
  // Starts slightly rotated (-15deg) and springs to 0.
  const rotationSpring = spring({
    frame,
    fps,
    config: {
      damping: 12,
      stiffness: 80,
    },
    from: -15,
    to: 0,
  });

  // 3. Impact Pulse
  // Triggered when the entrance is nearly complete (around frame 7-8).
  // This creates the "radiating outward" effect.
  const pulseStartFrame = 8;
  const pulseScale = interpolate(
    frame - pulseStartFrame,
    [0, 15],
    [0.8, 1.6],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const pulseOpacity = interpolate(
    frame - pulseStartFrame,
    [0, 5, 15],
    [0, glowIntensity * 0.8, 0], // Quick flash then fade
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 4. Steady Glow
  // Fades in as the pulse fades out to establish the "resting state".
  const steadyGlowOpacity = interpolate(
    frame,
    [15, 30],
    [0, glowIntensity],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 5. Dynamic Shadow/Glow Calculation
  // Mixes the pulse flash and the steady glow.
  // The 'drop-shadow' filter creates the glowing effect around the SVG path.
  const currentGlowOpacity = Math.max(pulseOpacity, steadyGlowOpacity);
  const glowFilter = `drop-shadow(0px 0px ${20 * entranceSpring}px ${glowColor}${Math.floor(currentGlowOpacity * 255).toString(16).padStart(2, '0')})`;

  // Logic to prevent parser errors
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Center positioning
  const x = width / 2;
  const y = height / 2;
  const halfSize = size / 2;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Background Pulse Circle (The "Shockwave") */}
      <div
        style={{
          position: "absolute",
          width: size,
          height: size,
          borderRadius: "50%",
          backgroundColor: glowColor,
          opacity: pulseOpacity * 0.5, // Subtler than the main glow
          transform: `scale(${pulseScale})`,
          filter: "blur(20px)",
        }}
      />

      {/* Main Checkmark Container */}
      <div
        style={{
          width: size,
          height: size,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          transform: `scale(${entranceSpring}) rotate(${rotationSpring}deg)`,
          filter: glowFilter,
          willChange: "transform", // Performance optimization
        }}
      >
        <svg
          width={size}
          height={size}
          viewBox="0 0 100 100"
          fill="none"
          stroke={checkColor}
          strokeWidth={strokeWidth}
          strokeLinecap="round"
          strokeLinejoin="round"
          style={{
            overflow: "visible", // Allows glow to spill out if needed
          }}
        >
          {/* 
            Standard Checkmark Geometry 
            M20 50: Start left
            L40 70: Down to bottom point
            L80 30: Up to top right
          */}
          <path d="M20 52 L40 72 L80 30" />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default ElasticCheckmark;